use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var entries = "";
    var first = true;

    for pony in herd.lineup() {
        let fed = herd.feed(pony: pony, scoops: 3);
        if !first {
            entries = entries.concat(other: ",");
        }
        entries = entries.concat(other: ledger.render(fed));
        first = false;
    }

    io.write(text: entries)?;
    return Ok(unit);
}

use stable.herd.{feed, lineup};
use stable.ledger.render;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = lineup();
    var entries = "";
    var index = 0;

    while index < ponies.len() {
        match ponies.get(index: index) {
            Some(pony) => {
                if index > 0 {
                    entries = entries.concat(other: ",");
                }
                let fed = feed(pony: pony, scoops: 3);
                entries = entries.concat(other: render(fed));
            },
            None => unit,
        };
        index = index + 1;
    }

    io.write(text: entries)?;
    return Ok(unit);
}

