use harbor.signal;

fn entries() -> String {
    var result = "";
    var first = true;

    for current in signal.today() {
        if !first {
            result = result.concat(other: ";");
        }

        let rendered = match current {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(density) => "fog:".concat(other: density),
        };

        result = result.concat(other: rendered);
        first = false;
    }

    result
}

