use mill.stock;
use mill.rules;

fn lines() -> String {
    var result = "";
    var first = true;
    for plank in stock.planks() {
        if rules.keep(plank) {
            if first {
                result = rules.label(plank);
                first = false;
            } else {
                result = result.concat(other: ",").concat(other: rules.label(plank));
            }
        }
    }
    result
}

