use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = menu.board();
    var i = 0;
    while i < board.length() {
        if i > 0 {
            io.write(text: ";")?;
        }
        kitchen.serve(dish: board[i], io: io)?;
        i = i + 1;
    }
    return Ok(unit);
}

